<script lang="ts">
	/**
	 * The Aphex logo, inlined rather than loaded from `/favicon.svg`.
	 *
	 * The file version carries its own `prefers-color-scheme` rule, which follows
	 * the *operating system* — so on a light-themed page viewed from a dark-mode OS
	 * it painted itself white and vanished into the card. Inlining lets it take
	 * `currentColor` and follow the app's theme, which is the only one that knows
	 * what it's sitting on.
	 *
	 * Two variants, because the two shapes aren't interchangeable:
	 *
	 * - `mark` — the square glyph. For tight, repeated spots where the product is
	 *   already obvious: app headers, nav rails, the favicon's sibling.
	 * - `lockup` — glyph plus wordmark, ~2.9:1. For the places that have to *say*
	 *   what this is, to someone who may have arrived from an email link: the sign-in
	 *   card, the 2FA challenge, invitations.
	 *
	 * Both are drawn from `currentColor` on `fill` *and* `stroke` — the glyph sits
	 * inside a stroked ring, so a single `fill` would leave the ring invisible.
	 */
	type Variant = 'mark' | 'lockup';

	let { variant = 'mark', class: className }: { variant?: Variant; class?: string } = $props();

	// `w-auto` on the lockup so a caller sets height and the width follows the
	// aspect ratio; a square default would squash the wordmark.
	const cls = $derived(className ?? (variant === 'lockup' ? 'h-8 w-auto' : 'h-10 w-10'));
</script>

